class Person:
    def __init__(self, name):
        self.name = name
    def greet(self):
        return f"Hi {self.name}"
print(Person("Ada").greet())

class Person {
    private final String name;
    Person(String name) {
        this.name = name;
    }
    String greet() {
        return "Hi " + name;
    }
}
System.out.println(new Person("Ada").greet());

struct Person {
    name: String,
}
impl Person {
    fn new(name: &str) -> Self {
        Person { name: name.to_string() }
    }
    fn greet(&self) -> String {
        format!("Hi {}", self.name)
    }
}
fn main() {
    println!("{}", Person::new("Ada").greet());
}

